def read_file(path, head=None, tail=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0526000" if __import__("os").path.isdir("./environment_mix/0526000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    import time

    def _audit(endpoint, status, detail=None):
        started = time.time()
        ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        # Maintain an audit log file even if not declared in schema.
        name = "usage_audit.json"
        rows = _load(name)
        if not isinstance(rows, list):
            rows = []
        row = {
            "id": f"ua_{int(time.time()*1000)}_{len(rows)+1}",
            "endpoint": endpoint,
            "timestamp": ts,
            "status": status,
            "latency_ms": None,
        }
        if detail is not None:
            row["detail"] = detail
        row["_started"] = started
        rows.append(row)
        _save(name, rows)
        return name, row["id"]

    def _audit_finish(audit_file, audit_id, status, latency_ms):
        rows = _load(audit_file)
        if isinstance(rows, list):
            for r in reversed(rows):
                if isinstance(r, dict) and r.get("id") == audit_id:
                    r["status"] = status
                    r["latency_ms"] = int(latency_ms)
                    if "_started" in r:
                        del r["_started"]
                    break
            _save(audit_file, rows)

    def _get_manifest():
        m = _load("fs_manifest.json")
        if isinstance(m, dict):
            root = m.get("root")
            allowed = m.get("allowed_directories")
            if isinstance(root, str) and isinstance(allowed, list) and all(isinstance(x, str) for x in allowed):
                return {"root": root, "allowed_directories": allowed}
        elif isinstance(m, list) and len(m) >= 1 and isinstance(m[0], dict):
            root = m[0].get("root")
            allowed = m[0].get("allowed_directories")
            if isinstance(root, str) and isinstance(allowed, list) and all(isinstance(x, str) for x in allowed):
                return {"root": root, "allowed_directories": allowed}
        # Default to database root; allow only within /app/database
        return {"root": _DB, "allowed_directories": [_DB]}

    def _is_within(path_abs, base_abs):
        path_abs = os.path.realpath(path_abs)
        base_abs = os.path.realpath(base_abs)
        try:
            common = os.path.commonpath([path_abs, base_abs])
        except Exception:
            return False
        return common == base_abs

    def _resolve_path(p):
        if not isinstance(p, str) or not p.strip():
            return None, _err("VALIDATION_ERROR", "Missing or invalid path")
        p = p.strip()

        manifest = _get_manifest()
        root = manifest["root"]
        allowed = manifest["allowed_directories"]

        # If relative, resolve under root
        if os.path.isabs(p):
            candidate = p
        else:
            candidate = os.path.join(root, p)

        candidate_real = os.path.realpath(candidate)

        # Must be within one of allowed directories (or equal to it)
        ok = any(_is_within(candidate_real, a) for a in allowed)
        if not ok:
            return None, _err("UNAUTHORIZED", "Path is outside allowed directories", allowed_directories=allowed)

        return candidate_real, None

    audit_file, audit_id = _audit("read_file", "STARTED")
    t0 = time.time()
    try:
        if head is not None and tail is not None:
            _audit_finish(audit_file, audit_id, "ERROR", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "Provide only one of head or tail")

        def _parse_n(x, which):
            if x is None:
                return None, None
            if not isinstance(x, (int, float)) or isinstance(x, bool):
                return None, _err("VALIDATION_ERROR", f"{which} must be a number")
            if int(x) != x:
                # Allow floats that are whole numbers? refuse per "non-numeric" / negative; treat non-integer as invalid
                return None, _err("VALIDATION_ERROR", f"{which} must be an integer")
            n = int(x)
            if n < 0:
                return None, _err("VALIDATION_ERROR", f"{which} must be non-negative")
            return n, None

        hn, e = _parse_n(head, "head")
        if e:
            _audit_finish(audit_file, audit_id, "ERROR", (time.time() - t0) * 1000)
            return e
        tn, e = _parse_n(tail, "tail")
        if e:
            _audit_finish(audit_file, audit_id, "ERROR", (time.time() - t0) * 1000)
            return e

        target, e = _resolve_path(path)
        if e:
            _audit_finish(audit_file, audit_id, "ERROR", (time.time() - t0) * 1000)
            return e

        if not os.path.exists(target):
            _audit_finish(audit_file, audit_id, "ERROR", (time.time() - t0) * 1000)
            return _err("NOT_FOUND", "Path does not exist", path=target)
        if not os.path.isfile(target):
            _audit_finish(audit_file, audit_id, "ERROR", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "Path is not a file", path=target)

        # Read as text; refuse if it appears binary by NUL heuristic
        try:
            with open(target, "rb") as f:
                raw = f.read()
        except PermissionError:
            _audit_finish(audit_file, audit_id, "ERROR", (time.time() - t0) * 1000)
            return _err("UNAUTHORIZED", "Insufficient permissions to read file", path=target)
        except FileNotFoundError:
            _audit_finish(audit_file, audit_id, "ERROR", (time.time() - t0) * 1000)
            return _err("NOT_FOUND", "Path does not exist", path=target)

        if b"\x00" in raw[:4096]:
            _audit_finish(audit_file, audit_id, "ERROR", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "File does not appear to be a text file", path=target)

        # Decode with a couple common encodings
        text = None
        for enc in ("utf-8", "utf-8-sig", "latin-1"):
            try:
                text = raw.decode(enc)
                break
            except UnicodeDecodeError:
                continue
        if text is None:
            _audit_finish(audit_file, audit_id, "ERROR", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "Unable to decode file as text", path=target)

        lines = text.splitlines()
        if hn is not None:
            out = "\n".join(lines[:hn])
        elif tn is not None:
            out = "\n".join(lines[-tn:] if tn != 0 else [])
        else:
            out = "\n".join(lines)

        _audit_finish(audit_file, audit_id, "OK", (time.time() - t0) * 1000)
        return {"path": target, "content": out, "truncated": (hn is not None or tn is not None)}
    except Exception as ex:
        _audit_finish(audit_file, audit_id, "ERROR", (time.time() - t0) * 1000)
        return _err("CONFLICT", "Unexpected error", detail=str(ex))

