def read_multiple_files(paths):
    import os
    root = os.path.join(_DB, "workspace")
    def resolve(p):
        p = str(p)
        cand = p if p.startswith(_DB) else os.path.join(root, p.lstrip("/"))
        if os.path.exists(cand): return cand
        base = os.path.basename(p)
        for dp, dn, fn in os.walk(root):
            if base in fn: return os.path.join(dp, base)
        return cand
    out = []
    plist = paths if isinstance(paths, list) else [paths]
    if not plist:
        plist = [os.path.join(root, "README.md")]
    for p in plist:
        rp = resolve(p)
        try:
            with open(rp, encoding="utf-8") as f:
                out.append(rp + ":\n" + f.read())
        except Exception as e:
            out.append(rp + ": Error - " + str(e))
    return "\n---\n".join(out)

