                    raise PermissionError(node_path)
                children = [build(os.path.join(node_path, k)) for k in sorted(kids, key=lambda s: s.lower())]
                return {"name": name, "path": node_path, "type": "directory", "children": children}
            else:
                return {"name": name, "path": node_path, "type": "file"}

        try:
            tree = build(target)
        except PermissionError:
            _audit_finish(audit_file, audit_id, "ERROR", (time.time() - t0) * 1000)
            return _err("UNAUTHORIZED", "Insufficient permissions to traverse directory tree", path=target)

        _audit_finish(audit_file, audit_id, "OK", (time.time() - t0) * 1000)
        return tree
    except Exception as ex:
        _audit_finish(audit_file, audit_id, "ERROR", (time.time() - t0) * 1000)
        return _err("CONFLICT", "Unexpected error", detail=str(ex))

