                    r["latency_ms"] = int(latency_ms)
                    if "_started" in r:
                        del r["_started"]
                    break
            _save(audit_file, rows)

    def _get_manifest():
        m = _load("fs_manifest.json")
        if isinstance(m, dict):
            root = m.get("root")
            allowed = m.get("allowed_directories")
            if isinstance(root, str) and isinstance(allowed, list) and all(isinstance(x, str) for x in allowed):
                return {"root": root, "allowed_directories": allowed}
        elif isinstance(m, list) and len(m) >= 1 and isinstance(m[0], dict):
            root = m[0].get("root")
            allowed = m[0].get("allowed_directories")
            if isinstance(root, str) and isinstance(allowed, list) and all(isinstance(x, str) for x in allowed):
                return {"root": root, "allowed_directories": allowed}
        return {"root": _DB, "allowed_directories": [_DB]}

    def _is_within(path_abs, base_abs):
        path_abs = os.path.realpath(path_abs)
        base_abs = os.path.realpath(base_abs)
        try:
            common = os.path.commonpath([path_abs, base_abs])
        except Exception:
            return False
        return common == base_abs

    def _resolve_path(p):
        if not isinstance(p, str) or not p.strip():
            return None, _err("VALIDATION_ERROR", "Missing or invalid path")
        p = p.strip()
        manifest = _get_manifest()
        root = manifest["root"]
        allowed = manifest["allowed_directories"]
        candidate = p if os.path.isabs(p) else os.path.join(root, p)
        candidate_real = os.path.realpath(candidate)
        if not any(_is_within(candidate_real, a) for a in allowed):
            return None, _err("UNAUTHORIZED", "Path is outside allowed directories", allowed_directories=allowed)
        return candidate_real, None

    audit_file, audit_id = _audit("get_file_info", "STARTED")
    t0 = time.time()
    try:
        target, e = _resolve_path(path)
        if e:
            _audit_finish(audit_file, audit_id, "ERROR", (time.time() - t0) * 1000)
            return e

        if not os.path.exists(target):
            _audit_finish(audit_file, audit_id, "ERROR", (time.time() - t0) * 1000)
            return _err("NOT_FOUND", "Path does not exist", path=target)

        try:
            st = os.stat(target)
        except PermissionError:
            _audit_finish(audit_file, audit_id, "ERROR", (time.time() - t0) * 1000)
            return _err("UNAUTHORIZED", "Insufficient permissions to inspect path", path=target)

        is_dir = os.path.isdir(target)
        is_file = os.path.isfile(target)
        mode = st.st_mode
        perms = stat.filemode(mode)

        info = {
            "path": target,
            "type": "directory" if is_dir else ("file" if is_file else "other"),
            "size": int(st.st_size) if is_file else 0,
            "created": datetime.datetime.utcfromtimestamp(st.st_ctime).isoformat() + "Z",
            "modified": datetime.datetime.utcfromtimestamp(st.st_mtime).isoformat() + "Z",
            "accessed": datetime.datetime.utcfromtimestamp(st.st_atime).isoformat() + "Z",
            "permissions": perms,
            "readable": os.access(target, os.R_OK),
            "writable": os.access(target, os.W_OK),
            "executable": os.access(target, os.X_OK),
        }

        _audit_finish(audit_file, audit_id, "OK", (time.time() - t0) * 1000)
        return info
    except Exception as ex:
        _audit_finish(audit_file, audit_id, "ERROR", (time.time() - t0) * 1000)
        return _err("CONFLICT", "Unexpected error", detail=str(ex))

